    -b               Flags the rasterizer to render without color
    -V, --version    Prints version information

OPTIONS:
    -x, --yaw <x>      Sets the object's static X rotation (in radians)
    -y, --pitch <y>    Sets the object's static Y rotation (in radians)
    -z, --roll <z>     Sets the object's static Z rotation (in radians)

ARGS:
    <input filename(s)>...    Sets the input file to render

SUBCOMMANDS:
    help     Prints this message or the help of the given subcommand(s)
    image    Generates a colorless terminal output as lines of text
"""

IMAGE_HELP_WITH_INPUTS = """executable-image 
Mitchell Hynes <mitchell.hynes@ecumene.xyz>
Generates a colorless terminal output as lines of text

USAGE:
    executable <input filename(s)>... image [FLAGS] [OPTIONS] -w <width>

FLAGS:
        --help       Prints help information
    -b               Flags the rasterizer to render without color
    -V, --version    Prints version information

OPTIONS:
    -j, --webify <frame count>    Generates a portable JS based render of your object for the web
    -h <height>                   Sets the height of the image to generate
    -w <width>                    Sets the width of the image to generate
    -x, --yaw <x>                 Sets the object's static X rotation (in radians)
    -y, --pitch <y>               Sets the object's static Y rotation (in radians)
    -z, --roll <z>                Sets the object's static Z rotation (in radians)
"""

IMAGE_HELP = IMAGE_HELP_WITH_INPUTS.replace("executable <input filename(s)>... image", "executable image")

CHARS = " .:-=+*#%@"
BG = (25,25,25)
BLACK = (0,0,0)
YELLOW = (255,255,0)

class Panic(Exception):
    def __init__(self, kind, msg):
        self.kind=kind; self.msg=msg

def rust_panic(line, msg):
    sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at src/inputs.rs:{line}:39:\n{msg}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)

def raster_panic(msg):
    sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at src/rasterizer.rs:90:33:\n{msg}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.exit(101)

def parse_float(s, default=0.0):
    try: return float(s)
    except Exception: return default

def vsub(a,b): return (a[0]-b[0],a[1]-b[1],a[2]-b[2])
def vcross(a,b): return (a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0])
def vdot(a,b): return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]
def vnorm(a):
    l=math.sqrt(vdot(a,a))
    return (0.0,0.0,0.0) if l==0 else (a[0]/l,a[1]/l,a[2]/l)

def rotate_pt(p, rx, ry, rz):
    x,y,z = p
    if rx:
        c,s=math.cos(rx),math.sin(rx); y,z = y*c-z*s, y*s+z*c
    if ry:
        c,s=math.cos(ry),math.sin(ry); x,z = x*c+z*s, -x*s+z*c
    if rz:
        c,s=math.cos(rz),math.sin(rz); x,y = x*c-y*s, x*s+y*c
    return (x,y,z)

def load_mtl(path):
    mats={}
    cur=None
    try:
        with open(path,'r',errors='ignore') as f:
            for raw in f:
                parts=raw.strip().split()
                if not parts: continue
                if parts[0]=='newmtl' and len(parts)>1:
                    cur=parts[1]; mats[cur]=(255,255,255)
                elif parts[0]=='Kd' and cur and len(parts)>=4:
                    vals=[]
                    for p in parts[1:4]:
                        try: vals.append(max(0,min(255,int(float(p)*255))))
                        except Exception: vals.append(0)
                    mats[cur]=tuple(vals)
    except Exception:
        raise Panic('mtl','Expected to have materials.: OpenFileFailed')
    return mats

def parse_face_index(tok, nverts):
    t=tok.split('/')[0]
    if not t: return None
    i=int(t)
    if i<0: i=nverts+i+1
    return i-1

def load_obj(filename):
    try:
        text=open(filename,'r',errors='ignore').read().splitlines()
    except Exception:
        raise Panic('load', f'called `Result::unwrap()` on an `Err` value: "filename: [{filename}] couldn\'t load, tobj couldnt load/parse OBJ. open file failed"')
    basedir=os.path.dirname(filename) or '.'
    mtllib=None
    for line in text:
        parts=line.strip().split()
        if parts and parts[0]=='mtllib' and len(parts)>1:
            mtllib=' '.join(parts[1:]); break
    if mtllib is None:
        # The observed binary expects material data for OBJ models.
        raise Panic('mtl','Expected to have materials.: OpenFileFailed')
    mats=load_mtl(os.path.join(basedir, mtllib))
    verts=[]; tris=[]; curmat=None
    for raw in text:
        line=raw.strip()
        if not line or line.startswith('#'): continue
        parts=line.split()
        tag=parts[0]
        if tag=='v' and len(parts)>=4:
            try: verts.append((float(parts[1]),float(parts[2]),float(parts[3])))
            except Exception: pass
        elif tag=='usemtl' and len(parts)>1:
            curmat=parts[1]
        elif tag=='f' and len(parts)>=4:
            idx=[]
            for p in parts[1:]:
                try:
                    ii=parse_face_index(p,len(verts))
                    if ii is not None: idx.append(ii)
                except Exception: pass
            if len(idx)>=3:
                col=mats.get(curmat,(255,255,255))
                # triangulate fan, as common OBJ loaders do
                for k in range(1,len(idx)-1):
                    try: tris.append((verts[idx[0]], verts[idx[k]], verts[idx[k+1]], col))
                    except Exception: pass
    return tris

def load_stl(filename):
    try:
        data=open(filename,'rb').read()
    except Exception as e:
        raise Panic('load', f'called `Result::unwrap()` on an `Err` value: "filename: [{filename}] couldn\'t load, STL load failed. No such file or directory (os error 2)"')
    tris=[]
    # ASCII STL parser; enough for the bundled assets and ordinary text STLs.
    try:
        txt=data.decode('utf-8','ignore')
        verts=[]
        for line in txt.splitlines():
            parts=line.strip().split()
            if len(parts)==4 and parts[0].lower()=='vertex':
                try: verts.append((float(parts[1]),float(parts[2]),float(parts[3])))
                except Exception: pass
                if len(verts)==3:
                    tris.append((verts[0],verts[1],verts[2],YELLOW)); verts=[]
    except Exception:
        pass
    if not tris and len(data)>=84:
        # Best effort binary STL fallback.
        import struct
        try:
            n=struct.unpack_from('<I',data,80)[0]; off=84
            for _ in range(min(n, (len(data)-84)//50)):
                # normal then three vertices
                vals=struct.unpack_from('<12f',data,off); off+=50
                tris.append(((vals[3],vals[4],vals[5]),(vals[6],vals[7],vals[8]),(vals[9],vals[10],vals[11]),YELLOW))
        except Exception:
            pass
    return tris

def load_inputs(first_arg):
    filenames=[x for x in first_arg.split(' ') if x!='']
    alltris=[]
    for fn in filenames:
        low=fn.lower()
        try:
            if low.endswith('.obj'):
                alltris.extend(load_obj(fn))
            elif low.endswith('.stl'):
                alltris.extend(load_stl(fn))
            else:
                raise Panic('load', f'called `Result::unwrap()` on an `Err` value: "filename: [{fn}] couldn\'t load, unknown filename extension. "')
        except Panic as p:
            if p.kind=='mtl': rust_panic(112,p.msg)
            else: rust_panic(126,p.msg)
    return alltris

def bary(px,py,a,b,c):
    den=(b[1]-c[1])*(a[0]-c[0])+(c[0]-b[0])*(a[1]-c[1])
    if den==0: return None
    w1=((b[1]-c[1])*(px-c[0])+(c[0]-b[0])*(py-c[1]))/den
    w2=((c[1]-a[1])*(px-c[0])+(a[0]-c[0])*(py-c[1]))/den
    w3=1-w1-w2
    return w1,w2,w3

def render_buffer(tris, width, height, rx=0.0, ry=0.0, rz=0.0):
    if width==0 or height==0:
        raster_panic('index out of bounds: the len is 0 but the index is 1')
    if width<0 or height<0: width=max(0,width); height=max(0,height)
    rtris=[]; pts=[]
    for a,b,c,col in tris:
        ra,rb,rc=rotate_pt(a,rx,ry,rz),rotate_pt(b,rx,ry,rz),rotate_pt(c,rx,ry,rz)
        rtris.append((ra,rb,rc,col)); pts += [ra,rb,rc]
    if not pts:
        pts=[(0,0,0)]
    minx,maxx=min(p[0] for p in pts),max(p[0] for p in pts)
    miny,maxy=min(p[1] for p in pts),max(p[1] for p in pts)
    sx=(width-1)/(maxx-minx) if maxx!=minx and width>1 else 1.0
    sy=(height-1)/(maxy-miny) if maxy!=miny and height>1 else 1.0
    def proj(p):
        x=(p[0]-minx)*sx if maxx!=minx else width/2
        y=(maxy-p[1])*sy if maxy!=miny else height/2
        return (x,y,p[2])
    grid=[' ']*(width*height)
    colors=[BLACK]*(width*height)
    zbuf=[-1e100]*(width*height)
    for a,b,c,col in rtris:
        n=vnorm(vcross(vsub(b,a),vsub(c,a)))
        nz=n[2]
        idx=int(nz*10.0)
        if idx<1: continue
        if idx>=len(CHARS): idx=len(CHARS)-1
        glyph=CHARS[idx]
        pa,pb,pc=proj(a),proj(b),proj(c)
        minbx=max(0,int(math.floor(min(pa[0],pb[0],pc[0]))))
        maxbx=min(width-1,int(math.ceil(max(pa[0],pb[0],pc[0]))))
        minby=max(0,int(math.floor(min(pa[1],pb[1],pc[1]))))
        maxby=min(height-1,int(math.ceil(max(pa[1],pb[1],pc[1]))))
        for yy in range(minby,maxby+1):
            for xx in range(minbx,maxbx+1):
                bc=bary(xx+0.5, yy+0.5, pa, pb, pc)
                if bc is None: continue
                w1,w2,w3=bc
                eps=-1e-9
                if w1>=eps and w2>=eps and w3>=eps:
                    z=w1*pa[2]+w2*pb[2]+w3*pc[2]
                    k=yy*width+xx
                    if z>=zbuf[k]:
                        zbuf[k]=z; grid[k]=glyph; colors[k]=col
    # The original stream is a flat raster with extra trailing padding. It only
    # materializes row breaks for rows containing rendered pixels, at an off-by-
    # one boundary; reproduce that externally visible quirk.
    out_len=(width+1)*height
    buf=[' ']*out_len
    bcols=[BLACK]*out_len
    for i,ch in enumerate(grid):
        if i<out_len:
            buf[i]=ch; bcols[i]=colors[i]
    for y in range(1,height):
        row=grid[y*width:(y+1)*width]
        if any(ch!=' ' for ch in row):
            pos=y*width+1
            if 0<=pos<out_len:
                buf[pos]='\n'; bcols[pos]=BLACK
    return buf,bcols

def emit_text(buf, cols, no_color):
    if no_color:
        sys.stdout.write(''.join(buf)+'\n')
    else:
        parts=[]
        for ch,col in zip(buf,cols):
            r,g,b=col
            parts.append(f"\x1b[48;2;25;25;25m\x1b[38;2;{r};{g};{b}m{ch}\x1b[49m\x1b[39m")
        parts.append('\n')
        sys.stdout.write(''.join(parts))

def emit_web(frames):
    sys.stdout.write('let frames = [\n')
    for i,(buf,cols) in enumerate(frames):
        sys.stdout.write('`\n')
        for ch,col in zip(buf,cols):
            r,g,b=col
            sys.stdout.write(f'<span style="color:rgb({r},{g},{b})">')
            if ch!='\n': sys.stdout.write(ch)
            else: sys.stdout.write('\n')
        sys.stdout.write('`' + (',' if i<len(frames)-1 else '];') + ('\n' if i<len(frames)-1 else ''))

def print_required():
    sys.stderr.write("error: The following required arguments were not provided:\n    <input filename(s)>...\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]\n\nFor more information try --help\n")
    sys.exit(1)

def err_unexpected(arg, usage='executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]'):
    sys.stderr.write(f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n")
    sys.exit(1)

def parse_int_value(s):
    if s.startswith('-'):
        err_unexpected(s, 'executable image [FLAGS] [OPTIONS] -w <width>')
    try: return int(s)
    except Exception:
        sys.stderr.write('Error: ParseIntError { kind: InvalidDigit }\n'); sys.exit(1)

def parse_cli(argv):
    if not argv: print_required()
    if argv[0]=='help':
        if len(argv)>1 and argv[1]=='image': print(IMAGE_HELP,end=''); sys.exit(0)
        print(MAIN_HELP,end=''); sys.exit(0)
    if argv[0] in ('-h','--help'):
        print(MAIN_HELP,end=''); sys.exit(0)
    if argv[0] in ('-V','--version'):
        print('Sloth 0.1'); sys.exit(0)
    if argv[0]=='image' and len(argv)>1 and argv[1]=='--help':
        print(IMAGE_HELP_WITH_INPUTS,end=''); sys.exit(0)
    if argv[0].startswith('-') and argv[0] not in ('-b','-x','--yaw','-y','--pitch','-z','--roll'):
        err_unexpected(argv[0])
    # Find subcommand token. Clap lets options/args precede it; image options follow it.
    img_index=None
    for i,a in enumerate(argv):
        if a=='image': img_index=i; break
    if img_index is not None:
        before=argv[:img_index]; after=argv[img_index+1:]
        if '--help' in after:
            print(IMAGE_HELP,end=''); sys.exit(0)
        # collect positional input(s), using only the first value as in the observed tool
        inputs=[]; no_color=False; i=0
        while i<len(before):
            a=before[i]
            if a=='-b': no_color=True; i+=1
            elif a in ('-x','--yaw','-y','--pitch','-z','--roll'):
                i+=2
            elif a in ('-V','--version'):
                print('Sloth 0.1'); sys.exit(0)
            elif a in ('-h','--help'):
                print(MAIN_HELP,end=''); sys.exit(0)
            elif a.startswith('-'):
                err_unexpected(a)
            else:
                inputs.append(a); i+=1
        if not inputs:
            # If invoked as `image ...` without help clap reports missing input at top level.
            print_required()
        width=None; height=10; web=None; rx=ry=rz=0.0
        i=0
        while i<len(after):
            a=after[i]
            if a=='-b': no_color=True; i+=1
            elif a in ('-V','--version'):
                print('Sloth 0.1'); sys.exit(0)
            elif a=='--width': err_unexpected(a,'executable image [FLAGS] [OPTIONS] -w <width>')
            elif a=='-w':
                if i+1>=len(after):
                    sys.stderr.write("error: The argument '-w <width>' requires a value but none was supplied\n"); sys.exit(1)
                width=parse_int_value(after[i+1]); i+=2
            elif a=='-h':
                if i+1>=len(after):
                    sys.stderr.write("error: The argument '-h <height>' requires a value but none was supplied\n"); sys.exit(1)
                height=parse_int_value(after[i+1]); i+=2
            elif a in ('-j','--webify'):
                if i+1>=len(after): sys.stderr.write("error: The argument '-j <frame count>' requires a value but none was supplied\n"); sys.exit(1)
                web=parse_int_value(after[i+1]); i+=2
            elif a in ('-x','--yaw'):
                rx=parse_float(after[i+1] if i+1<len(after) else '0'); i+=2
            elif a in ('-y','--pitch'):
                ry=parse_float(after[i+1] if i+1<len(after) else '0'); i+=2
            elif a in ('-z','--roll'):
                rz=parse_float(after[i+1] if i+1<len(after) else '0'); i+=2
            elif a.startswith('-'):
                err_unexpected(a,'executable image [FLAGS] [OPTIONS] -w <width>')
            else:
                # Extra words after subcommand are ignored by the renderer in practice less often;
                # treat them as unexpected for close clap-like behavior.
                err_unexpected(a,'executable image [FLAGS] [OPTIONS] -w <width>')
        if width is None:
            usage='executable image [FLAGS] [OPTIONS] -w <width>'
            if any(a=='-h' for a in after): usage='executable image -h <height> -w <width>'
            sys.stderr.write(f"error: The following required arguments were not provided:\n    -w <width>\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n")
            sys.exit(1)
        return {'mode':'image','input':inputs[0],'no_color':no_color,'w':width,'h':height,'web':web,'rx':rx,'ry':ry,'rz':rz}
    # terminal mode
    inputs=[]; no_color=False; rx=ry=rz=0.0; i=0
    while i<len(argv):
        a=argv[i]
        if a=='-b': no_color=True; i+=1
        elif a in ('-x','--yaw'):
            rx=parse_float(argv[i+1] if i+1<len(argv) else '0'); i+=2
        elif a in ('-y','--pitch'):
            ry=parse_float(argv[i+1] if i+1<len(argv) else '0'); i+=2
        elif a in ('-z','--roll'):
            rz=parse_float(argv[i+1] if i+1<len(argv) else '0'); i+=2
        elif a in ('-V','--version'):
            print('Sloth 0.1'); sys.exit(0)
        elif a in ('-h','--help'):
            print(MAIN_HELP,end=''); sys.exit(0)
        elif a.startswith('-'):
            err_unexpected(a)
        else:
            inputs.append(a); i+=1
    if not inputs: print_required()
    return {'mode':'term','input':inputs[0],'no_color':no_color,'rx':rx,'ry':ry,'rz':rz}

def main():
    opts=parse_cli(sys.argv[1:])
    tris=load_inputs(opts['input'])
    if opts['mode']=='image':
        w,h=opts['w'],opts['h']
        if opts['web'] is not None:
            n=opts['web']
            frames=[]
            for i in range(n):
                extra=(2*math.pi*i/n) if n else 0.0
                frames.append(render_buffer(tris,w,h,opts['rx']+extra,opts['ry'],opts['rz']))
            emit_web(frames)
        else:
            buf,cols=render_buffer(tris,w,h,opts['rx'],opts['ry'],opts['rz'])
            emit_text(buf,cols,opts['no_color'])
    else:
        if not sys.stdout.isatty():
            sys.stderr.write('Error: IoError(Os { code: 25, kind: Uncategorized, message: "Inappropriate ioctl for device" })\n')
            sys.exit(1)
        # Lightweight interactive-ish display: animate until interrupted.
        try:
            while True:
                w=int(os.environ.get('COLUMNS','80')); h=int(os.environ.get('LINES','24'))
                t=time.time()%6.283
                buf,cols=render_buffer(tris,max(1,w),max(1,h-1),opts['rx']+t,opts['ry'],opts['rz'])
                sys.stdout.write('\x1b[2J\x1b[H'); emit_text(buf,cols,opts['no_color']); sys.stdout.flush(); time.sleep(0.05)
        except KeyboardInterrupt:
